insert into public.guide_steps (guide_id, position, title_ar, title_en, body_ar, body_en, documents_ar, documents_en, link_url) values
  ((select id from g), 1, 'بلاغ الولادة من المستشفى', 'Birth notification from the hospital', 'يصدر المستشفى الذي تمت فيه الولادة بلاغ الولادة. تأكد قبل الخروج أن اسم الطفل وأسماء الوالدين مكتوبة بشكل صحيح.', 'The hospital where your baby was born issues the birth notification. Before you leave, check that the baby''s and parents'' names are spelled correctly.', array['البطاقة المدنية للوالدين','عقد الزواج']::text[], array['Both parents'' civil IDs','Marriage certificate']::text[], null),
  ((select id from g), 2, 'تقديم طلب شهادة الميلاد', 'Apply for the birth certificate', 'قدّم الطلب لدى إدارة تسجيل المواليد التابعة لوزارة الصحة أو عبر الخدمة الإلكترونية إن كانت متاحة. تحقق من الموقع الرسمي من المستندات والرسوم الحالية قبل الذهاب.', 'Apply at the Ministry of Health births registration office, or online if the e-service is available. Check the official site for the current documents and fees before you go.', array['بلاغ الولادة','البطاقة المدنية للوالدين','عقد الزواج','جوازات سفر الوالدين (للمقيمين)']::text[], array['Birth notification','Both parents'' civil IDs','Marriage certificate','Parents'' passports (residents)']::text[], 'https://www.moh.gov.kw'),
  ((select id from g), 3, 'استلام الشهادة والتأكد منها', 'Collect and check the certificate', 'راجع كل البيانات عند الاستلام. اطلب أكثر من نسخة لأنك ستحتاجها للبطاقة المدنية والجواز والإقامة.', 'Check every detail when you collect it. Ask for more than one copy: you''ll need it for the civil ID, passport and residency.', '{}'::text[], '{}'::text[], null);
insert into public.guide_steps (guide_id, position, title_ar, title_en, body_ar, body_en, documents_ar, documents_en, link_url) values
  ((select id from g), 1, 'جهّز المستندات', 'Prepare the documents', 'تحتاج عادة شهادة الميلاد وبطاقات الوالدين، وللمقيمين إقامة الطفل في الجواز. تحقق من الموقع الرسمي من المستندات والرسوم الحالية قبل الذهاب.', 'You usually need the birth certificate and the parents'' civil IDs; residents also need the child''s residency in the passport. Check the official site for the current documents and fees before you go.', array['شهادة الميلاد','البطاقة المدنية للوالدين','جواز الطفل مع الإقامة (للمقيمين)','صورة شخصية للطفل إن طُلبت']::text[], array['Birth certificate','Parents'' civil IDs','Child''s passport with residency (residents)','A photo of the child, if asked']::text[], null),
  ((select id from g), 2, 'قدّم الطلب', 'Apply', 'قدّم الطلب عبر موقع الهيئة أو تطبيقها (هويتي) أو في أحد فروعها.', 'Apply on the PACI website or app (Kuwait Mobile ID), or at a PACI branch.', '{}'::text[], '{}'::text[], 'https://www.paci.gov.kw'),
  ((select id from g), 3, 'استلم البطاقة', 'Collect the card', 'ستصلك رسالة عندما تكون البطاقة جاهزة للاستلام من جهاز التسليم الآلي أو الفرع.', 'You''ll get a message when the card is ready to collect from a PACI kiosk or branch.', '{}'::text[], '{}'::text[], null);
insert into public.guide_steps (guide_id, position, title_ar, title_en, body_ar, body_en, documents_ar, documents_en, link_url) values
  ((select id from g), 1, 'إضافة الطفل إلى ملف الجنسية', 'Add the child to the nationality file', 'تتم الإضافة لدى الإدارة العامة للجنسية ووثائق السفر بوزارة الداخلية. تحقق من الموقع الرسمي من المستندات والرسوم الحالية قبل الذهاب.', 'This is done at the Ministry of Interior nationality and travel documents department. Check the official site for the current documents and fees before you go.', array['شهادة الميلاد','شهادة جنسية الأب','البطاقة المدنية للوالدين']::text[], array['Birth certificate','Father''s nationality certificate','Parents'' civil IDs']::text[], 'https://www.moi.gov.kw'),
  ((select id from g), 2, 'طلب الجواز', 'Apply for the passport', 'قدّم طلب الجواز مع صور الطفل بالمواصفات المطلوبة.', 'Apply for the passport with photos of the child in the required format.', array['صور شخصية حديثة','البطاقة المدنية للطفل']::text[], array['Recent photos','Child''s civil ID']::text[], 'https://www.moi.gov.kw');
insert into public.guide_steps (guide_id, position, title_ar, title_en, body_ar, body_en, documents_ar, documents_en, link_url) values
  ((select id from g), 1, 'تواصل مع سفارة بلدك', 'Contact your embassy', 'كل سفارة لها إجراءاتها ومواعيدها. اسأل عن المستندات المطلوبة ومدة الإصدار.', 'Each embassy has its own steps and appointments. Ask which documents they need and how long it takes.', array['شهادة الميلاد (قد تحتاج تصديق وزارة الخارجية)','جوازات الوالدين','صور الطفل']::text[], array['Birth certificate (may need Ministry of Foreign Affairs attestation)','Parents'' passports','Photos of the child']::text[], null),
  ((select id from g), 2, 'استلم الجواز ثم ابدأ الإقامة', 'Collect the passport, then start the residency', 'بعد استلام الجواز انتقل إلى دليل "إقامة الطفل".', 'Once you have the passport, go to the "Residency for your child" guide.', '{}'::text[], '{}'::text[], null);
insert into public.guide_steps (guide_id, position, title_ar, title_en, body_ar, body_en, documents_ar, documents_en, link_url) values
  ((select id from g), 1, 'جهّز المستندات', 'Prepare the documents', 'قد يُطلب إثبات راتب العائل وعقد الإيجار وتأمين صحي. هناك مهلة بعد الولادة لتقديم طلب الإقامة، فلا تتأخر. تحقق من الموقع الرسمي من المستندات والرسوم الحالية قبل الذهاب.', 'You may need the sponsoring parent''s salary proof, a lease and health insurance. There is a deadline after the birth to apply, so don''t wait. Check the official site for the current documents and fees before you go.', array['جواز الطفل','شهادة الميلاد','جواز وإقامة العائل','إثبات الراتب','عقد الإيجار']::text[], array['Child''s passport','Birth certificate','Sponsor''s passport and residency','Salary proof','Lease']::text[], null),
  ((select id from g), 2, 'ادفع التأمين الصحي', 'Pay the health insurance', 'يُدفع رسم الضمان الصحي للطفل قبل إصدار الإقامة.', 'The child''s health insurance fee is paid before the residency is issued.', '{}'::text[], '{}'::text[], null),
  ((select id from g), 3, 'قدّم طلب الإقامة', 'Apply for the residency', 'قدّم الطلب لدى إدارة شؤون الإقامة في محافظتك أو عبر الخدمة الإلكترونية.', 'Apply at the residency affairs department for your governorate, or online.', '{}'::text[], '{}'::text[], 'https://www.moi.gov.kw'),
  ((select id from g), 4, 'البطاقة المدنية', 'Civil ID', 'بعد الإقامة اطلب البطاقة المدنية للطفل (راجع دليل البطاقة المدنية).', 'After the residency, apply for the child''s civil ID (see the civil ID guide).', '{}'::text[], '{}'::text[], null);
insert into public.guide_steps (guide_id, position, title_ar, title_en, body_ar, body_en, documents_ar, documents_en, link_url) values
  ((select id from g), 1, 'اعرف مركزك الصحي', 'Find your health centre', 'يتبع كل عنوان مركزاً صحياً محدداً حسب المنطقة.', 'Each address belongs to one health centre by area.', '{}'::text[], '{}'::text[], null),
  ((select id from g), 2, 'سجّل الطفل وخذ دفتر التطعيم', 'Register and get the vaccination booklet', 'أحضر البطاقة المدنية للطفل أو شهادة الميلاد إن لم تصدر البطاقة بعد.', 'Bring the child''s civil ID, or the birth certificate if the civil ID isn''t ready yet.', array['البطاقة المدنية للطفل أو شهادة الميلاد','البطاقة المدنية لأحد الوالدين']::text[], array['Child''s civil ID or birth certificate','A parent''s civil ID']::text[], null);
insert into public.guide_steps (guide_id, position, title_ar, title_en, body_ar, body_en, documents_ar, documents_en, link_url) values
  ((select id from g), 1, 'تحقق من موعد التسجيل والعمر المطلوب', 'Check the registration dates and age', 'تعلن وزارة التربية مواعيد التسجيل وشرط العمر كل سنة. المدارس الخاصة لها مواعيدها الخاصة.', 'The Ministry of Education announces registration dates and the age rule each year. Private schools set their own dates.', '{}'::text[], '{}'::text[], 'https://www.moe.edu.kw'),
  ((select id from g), 2, 'جهّز المستندات', 'Prepare the documents', 'تحقق من الموقع الرسمي من المستندات والرسوم الحالية قبل الذهاب.', 'Check the official site for the current documents and fees before you go.', array['البطاقة المدنية للطفل','شهادة الميلاد','شهادة التطعيمات','صور شخصية']::text[], array['Child''s civil ID','Birth certificate','Vaccination certificate','Photos']::text[], null),
  ((select id from g), 3, 'قدّم الطلب', 'Apply', 'المدارس الحكومية: حسب منطقة السكن. المدارس الخاصة: مباشرة لدى المدرسة.', 'Government schools: by home area. Private schools: directly with the school.', '{}'::text[], '{}'::text[], null);
