  ('hospital', 'مستشفى مبارك الكبير', 'Mubarak Al-Kabeer Hospital', 'hawalli', 'الجابرية', 'Jabriya', 'مستشفى حكومي عام فيه قسم للأطفال.', 'Government general hospital with a children''s department.', 'https://www.google.com/maps/search/?api=1&query=Mubarak%20Al-Kabeer%20Hospital%20Kuwait', 'published'),
